"""Controller and episode notes for reflection_qa instance i00."""
import json
import numpy as np
from rcb_client import Robot

r = Robot()
spec = r.spec()
layout = spec["proprio_layout"]

def now_vector(res):
    p = res.meta.get("proprio", {}).get("now", {})
    if isinstance(p, dict):
        return np.array([p[k] for k in layout], dtype=float)
    return np.asarray(p, dtype=float)

def joint_targets(q, fingers=(0.04, 0.04)):
    q = np.asarray(q, dtype=float)
    return np.r_[q[:7], fingers]

def hold(target, seconds, cameras=None, video="none"):
    n = max(1, int(round(seconds / spec["control_dt"])))
    return r.submit("joint_position", np.tile(np.asarray(target, dtype=float), (n, 1)),
                    dt=spec["control_dt"], interpolate="hold", cameras=cameras, video=video)

def capture(cameras=None, depth=False):
    return r.get_obs(cameras=cameras, include_depth=depth, video="frames")

if __name__ == "__main__":
    print(json.dumps({"spec": spec, "status": r.status()}, indent=2, default=str))
    obs = capture()
    for cam, im in obs.last.items():
        from PIL import Image
        Image.fromarray(im).save(f"/app/output/start_{cam}.png")
    print("saved initial images", list(obs.last))
